+static void shell_ap_console_reset_parser(void)
+{
+	cmd_line_buf.cur_cmd_type = CMD_TYPE_INVALID;
+	cmd_line_buf.cmd_data_len = 0;
+	cmd_line_buf.bkreg_state = BKREG_WAIT_01;
+	cmd_line_buf.bkreg_left_byte = 0;
+	cmd_line_buf.cmd_ovf_hint = 0;
+	s_ap_escape_pending = 0;
+	cmd_dev->dev_drv->io_ctrl(cmd_dev, SHELL_IO_CTRL_RX_RESET, NULL);
