+
+static void shell_ap_console_switch_process(void)
+{
+	if (s_ap_link_down_request)
+	{
+		s_ap_link_down_request = 0;
+		s_ap_open_request = 0;
+		s_ap_close_request = 0;
+		if (s_uart0_owner != UART0_OWNER_CP_CLI)
+		{
+			s_uart0_owner = UART0_OWNER_TO_CP_PENDING;
+			ap_console_bridge_purge_tx();
+			(void)ap_console_bridge_set_output_mode(AP_CONSOLE_OUTPUT_LOG);
+			shell_set_log_level(s_ap_saved_log_level);
+			shell_ap_console_reset_parser();
+			s_uart0_owner = UART0_OWNER_CP_CLI;
+			shell_log_raw_data((const u8 *)"\r\nAP link down; returned to CP CLI\r\n$",
+					   sizeof("\r\nAP link down; returned to CP CLI\r\n$") - 1);
+		}
+		return;
+	}
+
+	if (s_ap_close_request)
+	{
+		s_ap_close_request = 0;
+		s_ap_open_request = 0;
+		if (s_uart0_owner == UART0_OWNER_AP_CONSOLE)
+		{
+			ap_console_bridge_stats_t stats;
+			s_uart0_owner = UART0_OWNER_TO_CP_PENDING;
+			ap_console_bridge_purge_tx();
+			(void)ap_console_bridge_set_output_mode(AP_CONSOLE_OUTPUT_LOG);
+			shell_set_log_level(s_ap_saved_log_level);
+			shell_ap_console_reset_parser();
+			s_uart0_owner = UART0_OWNER_CP_CLI;
+			ap_console_bridge_get_stats(&stats);
+			shell_cmd_ind_out("AP console input drops: %u\r\n",
+					  (unsigned)(stats.tx_drop - s_ap_open_drop));
+			shell_log_raw_data((const u8 *)"\r\nAP console closed\r\n$",
+					   sizeof("\r\nAP console closed\r\n$") - 1);
+		}
+		return;
+	}
+
+	if (s_ap_open_request)
+	{
+		ap_console_bridge_stats_t stats;
+
+		s_ap_open_request = 0;
+		s_uart0_owner = UART0_OWNER_TO_AP_PENDING;
+		if (!ap_console_bridge_is_ready())
+		{
+			s_uart0_owner = UART0_OWNER_CP_CLI;
+			shell_log_raw_data((const u8 *)"\r\nAP console unavailable\r\n$",
+					   sizeof("\r\nAP console unavailable\r\n$") - 1);
+			return;
+		}
+
+		shell_ap_console_reset_parser();
+		if (ap_console_bridge_set_output_mode(AP_CONSOLE_OUTPUT_RAW) != BK_OK)
+		{
+			s_uart0_owner = UART0_OWNER_CP_CLI;
+			shell_log_raw_data((const u8 *)"\r\nAP console mode switch timeout\r\n$",
+					   sizeof("\r\nAP console mode switch timeout\r\n$") - 1);
+			return;
+		}
+		s_ap_saved_log_level = shell_get_log_level();
+		shell_set_log_level(BK_LOG_ERROR);
+		ap_console_bridge_get_stats(&stats);
+		s_ap_open_drop = stats.tx_drop;
+		s_uart0_owner = UART0_OWNER_AP_CONSOLE;
+		shell_log_raw_data((const u8 *)"\r\nAP console open; exit with Ctrl-], release, then press .\r\n",
+				   sizeof("\r\nAP console open; exit with Ctrl-], release, then press .\r\n") - 1);
+	}
+}
+
+void shell_ap_console_link_down(void)
+{
+	if (s_uart0_owner == UART0_OWNER_AP_CONSOLE ||
+		s_uart0_owner == UART0_OWNER_TO_AP_PENDING)
+	{
+		s_ap_link_down_request = 1;
+		set_shell_event(&shell_task_event, SHELL_EVENT_AP_SWITCH);
+	}
+}
