+void shell_ap_console_command(char *pcWriteBuffer, int xWriteBufferLen,
+				      int argc, char **argv)
+{
+	ap_console_bridge_stats_t stats;
+
+	if (argc != 2)
+	{
+		snprintf(pcWriteBuffer, xWriteBufferLen,
+			 "usage: ap_console open|close|status\r\n");
+		return;
+	}
+
+	if (!strcmp(argv[1], "open"))
+	{
+		if (s_uart0_owner != UART0_OWNER_CP_CLI)
+			snprintf(pcWriteBuffer, xWriteBufferLen, "AP console busy\r\n");
+		else if (!ap_console_bridge_is_ready())
+			snprintf(pcWriteBuffer, xWriteBufferLen,
+				 "AP console link not ready\r\n");
+		else
+		{
+			s_ap_open_request = 1;
+			snprintf(pcWriteBuffer, xWriteBufferLen,
+				 "switching UART0 to AP console...\r\n");
+		}
+		return;
+	}
+
+	if (!strcmp(argv[1], "close"))
+	{
+		if (s_uart0_owner == UART0_OWNER_AP_CONSOLE)
+		{
+			s_ap_close_request = 1;
+			set_shell_event(&shell_task_event, SHELL_EVENT_AP_SWITCH);
+		}
+		snprintf(pcWriteBuffer, xWriteBufferLen,
+			 s_uart0_owner == UART0_OWNER_CP_CLI ?
+			 "AP console already closed\r\n" : "AP console closing\r\n");
+		return;
+	}
+
+	if (strcmp(argv[1], "status"))
+	{
+		snprintf(pcWriteBuffer, xWriteBufferLen,
+			 "usage: ap_console open|close|status\r\n");
+		return;
+	}
+
+	ap_console_bridge_get_stats(&stats);
+	shell_cmd_ind_out("bridge rx=%u tx=%u drop=%u part=%u qfail=%u "
+			  "down=%u reset=%u timeout=%u st=%x\r\n",
+			  (unsigned)stats.rx_bytes, (unsigned)stats.tx_bytes,
+			  (unsigned)stats.tx_drop, (unsigned)stats.tx_partial,
+			  (unsigned)stats.rx_queue_fail, (unsigned)stats.link_down,
+		 (unsigned)stats.reset, (unsigned)stats.timeout,
+		 stats.mb_status);
+	shell_cmd_ind_out("ready=0x%x state=%u badenv=%u ackretry=%u ackfull=%u badreset=%u\r\n",
+			  stats.ready_flags, stats.transport_state,
+			  (unsigned)stats.bad_envelope, (unsigned)stats.ack_retry,
+			  (unsigned)stats.ack_queue_full, (unsigned)stats.reset_bad);
+	snprintf(pcWriteBuffer, xWriteBufferLen,
+		 "owner=%s link=%s mode=%s q=%u free=%u mbrx=%u active=%u/%x/%u/%u\r\n",
+		 s_uart0_owner == UART0_OWNER_CP_CLI ? "CP_CLI" :
+		 s_uart0_owner == UART0_OWNER_AP_CONSOLE ? "AP_CONSOLE" : "PENDING",
+		 stats.link_ready ? "ready" : "down",
+		 stats.output_mode == AP_CONSOLE_OUTPUT_RAW ? "RAW" : "LOG",
+		 stats.tx_queued, stats.mb_tx_free, stats.mb_rx_ready,
+		 stats.active_busy, stats.active_channel, stats.active_sequence,
+		 stats.active_command);
+}
