+	if (ctrl == MBOX0_CTRL_SYNC_TX)
+	{
+		if (slots->sync_used)
+			return NULL;
+		slots->sync_used = 1;
+		slots->sync_order = ++slots->publish_order;
+		*kind = 3;
+		return &slots->sync;
+	}
