+	for (i = 0; i < MBOX0_CMD_SLOT_NUM; i++)
+	{
+		if (!slots->cmd_used[i])
+		{
+			slots->cmd_used[i] = 1;
+			slots->cmd_order[i] = ++slots->publish_order;
+			slots->cmd_active = i + 1;
+			*kind = 0;
+			*index = i;
+			return &slots->cmd[i];
+		}
