+	ctrl = (desc->data.param0 >> 12) & 0x0f;
+	if ((ctrl & MBOX0_CTRL_ACK_BOX) == 0)
+	{
+		adapter_diag.last_cmd_header = desc->data.param0;
+		adapter_diag.cmd_received++;
